- case: testAttrsKwOnlyClass
  main: |
    import attr
    @attr.s(kw_only=True, auto_attribs=True)
    class A:
        a: int
        b: bool
    A()  # E: Missing named argument "a" for "A"  [call-arg] # E: Missing named argument "b" for "A"  [call-arg]
